/* Gentlemen's Lunch website. Reads data/index.json and data/<season>.json (generated by scripts/build.py). */
(function () {
  "use strict";

  const TABS = [
    ["standings", "Standings"],
    ["picks", "Picks"],
    ["schedule", "Schedule & Results"],
    ["markets", "Markets"],
    ["history", "History"],
    ["rules", "Rules"],
  ];
  const state = { index: null, data: null, season: null, tab: "standings", picksView: "category", player: null };
  const cache = {};
  const $ = (sel) => document.querySelector(sel);

  // ---------------------------------------------------------------- helpers
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  function parseDate(s) { if (!s) return null; const [y, m, d] = s.slice(0, 10).split("-").map(Number); return new Date(y, m - 1, d); }
  function fmtDate(s) { const d = parseDate(s); return d ? `${MONTHS[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}` : ""; }
  const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  function fmtDay(s) { const d = parseDate(s); return d ? `${DAYS[d.getDay()]}, ${fmtDate(s)}` : ""; }
  function fmtStamp(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    return d.toLocaleString(undefined, { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" });
  }
  function fmtValue(v, unit) {
    if (v === null || v === undefined || v === "") return "—";
    const n = typeof v === "number" ? v : Number(String(v).replace(/[$,]/g, ""));
    if (Number.isNaN(n)) return esc(v);
    if (unit === "pct") return (n <= 1 ? n * 100 : n).toFixed(1).replace(/\.0$/, "") + "%";
    if (unit === "usd") return "$" + (Math.abs(n) >= 1000 ? Math.round(n).toLocaleString() : n.toFixed(2).replace(/\.00$/, ""));
    return n.toLocaleString();
  }
  const playerName = (id) => (state.data.players.find((p) => p.id === id) || { name: id }).name;
  const ptsBadge = (n) => `<span class="pts p${n || 0}">${n ? "+" + n : "–"}</span>`;
  function chip(status) {
    const label = { final: "Final", live: "Live", pending: "Upcoming" }[status] || status;
    return `<span class="chip ${esc(status)}">${label}</span>`;
  }
  function pickText(cat, pick) {
    if (pick === null || pick === undefined || pick === "") return '<span class="meta">no pick</span>';
    if (cat.type === "closest") return fmtValue(pick, cat.unit);
    if (cat.type === "ranking") return esc(String(pick).split(",").join(" › "));
    return esc(pick);
  }
  function resultText(cat) {
    const r = cat.result || {};
    if (cat.type === "winner_runnerup") {
      if (!r.winner) return null;
      return `<b>${esc(r.winner)}</b>` + (r.runner_up ? ` over ${esc(r.runner_up)}` : "") + (cat.result_meta.score ? ` (${esc(cat.result_meta.score)})` : "");
    }
    if (cat.type === "exact") return r.answer ? `<b>${esc(r.answer)}</b>` : null;
    if (cat.type === "closest") return r.value !== null && r.value !== undefined ? `<b>${fmtValue(r.value, cat.unit)}</b>` : null;
    if (cat.type === "ranking") return r.order ? `<b>${esc(r.order.join(" › "))}</b>` : null;
    return null;
  }
  function scorers(cat) {
    const list = Object.entries(cat.points_awarded).filter(([, p]) => p > 0).sort((a, b) => b[1] - a[1]);
    if (!list.length) return cat.status === "pending" ? "" : "Nobody scored";
    return list.map(([id, p]) => `${esc(playerName(id))} +${p}`).join(", ");
  }
  const isActive = () => state.data.season.status === "active";
  const isPreview = () => state.data.season.status === "planning" || state.data.season.status === "picks_open";

  // ---------------------------------------------------------------- routing
  function readHash() {
    const [tab, season] = location.hash.replace(/^#/, "").split("/");
    if (TABS.some(([id]) => id === tab)) state.tab = tab;
    if (season) state.season = season;
  }
  function writeHash() {
    const s = state.season === state.index.active ? "" : "/" + state.season;
    history.replaceState(null, "", "#" + state.tab + s);
  }

  async function loadSeason(id) {
    if (!cache[id]) {
      const res = await fetch(`data/${id}.json`, { cache: "no-cache" });
      cache[id] = await res.json();
    }
    state.data = cache[id];
  }

  // ---------------------------------------------------------------- shell
  function renderShell() {
    const sel = $("#season");
    sel.innerHTML = state.index.seasons
      .map((s) => `<option value="${esc(s.id)}"${s.id === state.season ? " selected" : ""}>${esc(s.id)}${s.status === "final" ? " (final)" : s.status === "planning" || s.status === "picks_open" ? " (preview)" : s.id === state.index.active ? " (current)" : ""}</option>`)
      .join("");
    $("#tabs").innerHTML = TABS.map(([id, label]) => `<button class="tab" role="tab" data-tab="${id}" aria-selected="${id === state.tab}">${label}</button>`).join("");
    const s = state.data.season;
    $("#sub").textContent = isPreview()
      ? `${s.year} season · picks due ${fmtDate(s.picks_close)}`
      : `${s.year} season · ${s.status === "final" ? "settled" : "settles"} ${fmtDate(s.settlement_date)}`;
    const parts = [`Updated ${fmtStamp(state.data.generated_at)}`];
    if (state.data.prices_as_of && isActive()) parts.push(`market prices as of ${fmtStamp(state.data.prices_as_of)}`);
    $("#foot").innerHTML = esc(parts.join(" · ")) + ". Questions? Ask Robert.";
  }

  function render() {
    renderShell();
    let view = { standings, picks, schedule, markets, historyTab, rules }[state.tab === "history" ? "historyTab" : state.tab];
    if (isPreview()) {
      if (state.tab === "standings") view = () => underConstruction("Standings", "The leaderboard goes up once picks close. Nobody has any points yet, so technically everyone is tied for first.");
      if (state.tab === "markets") view = () => underConstruction("Markets", "Starting prices get locked in when picks close. Until then, today's prices are on the Picks tab.");
      if (state.tab === "picks") view = previewPicks;
    }
    $("#view").innerHTML = view();
    writeHash();
  }

  // ---------------------------------------------------------------- next-season preview
  const CONE = `<svg class="construction" viewBox="0 0 240 120" aria-hidden="true">
    <defs><pattern id="stripes" width="20" height="20" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
      <rect width="10" height="20" fill="#f28c28"/><rect x="10" width="10" height="20" fill="#fff"/></pattern></defs>
    <rect x="20" y="22" width="150" height="26" rx="4" fill="url(#stripes)" stroke="#1f2420" stroke-width="2"/>
    <rect x="34" y="48" width="8" height="58" fill="#5d645d"/><rect x="148" y="48" width="8" height="58" fill="#5d645d"/>
    <rect x="24" y="104" width="28" height="6" rx="2" fill="#1f2420"/><rect x="138" y="104" width="28" height="6" rx="2" fill="#1f2420"/>
    <path d="M200 30 L222 106 H178 Z" fill="#f28c28" stroke="#1f2420" stroke-width="2"/>
    <path d="M193 54 H207 L211 68 H189 Z" fill="#fff"/><path d="M186 80 H214 L218 94 H182 Z" fill="#fff"/>
    <rect x="170" y="104" width="60" height="7" rx="2" fill="#1f2420"/></svg>`;

  function underConstruction(what, msg) {
    const s = state.data.season;
    return `<div class="card uc">${CONE}<h2>${esc(what)}: under construction</h2>
      <p>${esc(msg)}</p>
      <p class="meta">Picks are due ${esc(fmtDay(s.picks_close))} at 11:59 pm ET.</p></div>`;
  }

  function previewPicks() {
    const d = state.data;
    const s = d.season;
    const sheet = d.sheet_url ? ` <a href="${esc(d.sheet_url)}" target="_blank" rel="noopener">Printable picks sheet</a>` : "";
    const banner = `<div class="card leader preview-banner">${JACKET}<div><div class="eyebrow">Coming soon</div>
      <div class="who">${esc(s.title)} picks</div>
      <p>Here's this year's lineup. The picks form goes live <b>no later than this year's lunch</b>, and the survey closes
      <b>${esc(fmtDay(s.picks_close))} at 11:59 pm ET</b>.${sheet}</p></div></div>`;
    const groups = [...new Set(d.categories.map((c) => c.group))];
    let n = 0;
    const body = groups.map((g) => `<h2>${esc(g)}</h2><div class="card"><ul class="rows tpl">${d.categories.filter((c) => c.group === g).map((c) => {
      n += 1;
      const today = (d.today || {})[c.id];
      return `<li><span class="num">${n}</span><span><b>${esc(c.name)}</b><span class="sub2">${esc(c.question)}</span>
        ${today ? `<span class="sub2">${c.type === "closest" || c.type === "ranking" ? "Today" : "FYI"}: ${esc(today)}</span>` : ""}</span><span class="meta">${pointsLabel(c)}</span></li>`;
    }).join("")}</ul></div>`).join("");
    return banner + body;
  }

  // ---------------------------------------------------------------- standings
  const JACKET = `<svg class="jacket" viewBox="0 0 64 64" aria-hidden="true"><path d="M22 6l10 8 10-8 12 6 6 20-8 3v23H12V35l-8-3 6-20z" fill="#7b1e30"/><path d="M32 14l-6 18 6 26 6-26z" fill="#561421"/><path d="M26 6l6 8 6-8" fill="none" stroke="#f7f4ec" stroke-width="2"/><circle cx="32" cy="38" r="1.6" fill="#e9c46a"/><circle cx="32" cy="45" r="1.6" fill="#e9c46a"/></svg>`;

  function standings() {
    const d = state.data;
    const active = isActive();
    const rows = active ? d.standings_projected : d.standings_current;
    const top = rows.filter((r) => r.rank === 1);
    const names = top.map((r) => playerName(r.player)).join(" & ");
    const eyebrow = active ? (top.length > 1 ? "Tied for the lead (projected)" : "Leading (projected)") : top.length > 1 ? "Co-Champions" : "Champion";
    const leader = `<div class="card leader">${JACKET}<div><div class="eyebrow">${eyebrow}</div><div class="who">${esc(names)}</div><div class="pts-big">${top[0].points} points</div></div></div>`;

    const cur = Object.fromEntries(d.standings_current.map((r) => [r.player, r]));
    const proj = Object.fromEntries(d.standings_projected.map((r) => [r.player, r]));
    const max = Math.max(1, ...rows.map((r) => r.points));
    const body = rows.map((r) => `
      <tr class="${r.rank === 1 ? "top1" : ""}">
        <td class="rank">${r.rank}</td>
        <td class="name">${esc(playerName(r.player))}${r.rank === 1 ? ' <span class="star" aria-label="leader">★</span>' : ""}<div class="bar"><span style="width:${(100 * r.points) / max}%"></span></div></td>
        ${active ? `<td class="num">${cur[r.player].points}</td>` : ""}
        <td class="num big">${active ? proj[r.player].points : r.points}</td>
      </tr>`).join("");
    const head = active ? `<th>#</th><th>Player</th><th class="num">Locked in</th><th class="num">Projected</th>` : `<th>#</th><th>Player</th><th class="num">Final</th>`;
    const table = `<div class="card" style="margin-top:12px"><table class="standings"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>
      ${active ? `<p class="note"><b>Locked in</b> counts categories that are finished. <b>Projected</b> also counts the market picks as if the season ended at today's prices.</p>` : ""}</div>`;

    let next = "";
    if (active) {
      const upcoming = d.categories.filter((c) => c.status !== "final")
        .sort((a, b) => (a.date || "").localeCompare(b.date || "")).slice(0, 4);
      if (upcoming.length) {
        next = `<h2>Coming up</h2><div class="card"><ul class="sched">${upcoming.map(schedItem).join("")}</ul></div>`;
      }
    }
    return leader + table + next;
  }

  // ---------------------------------------------------------------- picks
  function picks() {
    const d = state.data;
    const seg = `<div class="seg" role="group" aria-label="View">
      <button data-pv="category" aria-pressed="${state.picksView === "category"}">By category</button>
      <button data-pv="player" aria-pressed="${state.picksView === "player"}">By player</button>
      <button class="only-wide" data-pv="grid" aria-pressed="${state.picksView === "grid"}">Full grid</button></div>`;
    if (state.picksView === "player") return seg + picksByPlayer();
    if (state.picksView === "grid") return seg + picksGrid();
    const groups = [...new Set(d.categories.map((c) => c.group))];
    return seg + groups.map((g) => `<h2>${esc(g)}</h2><div class="grid two">${d.categories.filter((c) => c.group === g).map(catCard).join("")}</div>`).join("");
  }

  function catCard(c) {
    const res = resultText(c);
    const order = Object.keys(c.picks).sort((a, b) => (c.points_awarded[b] || 0) - (c.points_awarded[a] || 0));
    const rows = order.map((p) => {
      const pts = c.points_awarded[p] || 0;
      const det = c.detail[p] || {};
      let extra = "";
      if (c.type === "closest" && det.distance !== undefined && c.status !== "pending") extra = `<span class="sub2">off by ${fmtValue(det.distance, c.unit)}</span>`;
      if (c.type === "ranking" && det.score !== undefined) extra = `<span class="sub2">${det.score} spots off</span>`;
      return `<li class="${pts ? "scored" : ""}"><span class="who">${esc(playerName(p))}</span><span class="pick">${pickText(c, c.picks[p])}${extra}</span>${ptsBadge(pts)}</li>`;
    }).join("");
    const label = c.status === "live" ? "Right now" : "Result";
    return `<div class="card">
      <div class="cat-head"><div><h3>${esc(c.name)}</h3><div class="meta">${esc(fmtDate(c.date))} · ${pointsLabel(c)}</div></div>${chip(c.status)}</div>
      ${res ? `<div class="result">${label}: ${res}</div>` : ""}
      <ul class="rows">${rows}</ul></div>`;
  }

  function pointsLabel(c) {
    if (c.type === "winner_runnerup") return "5 pts winner · 3 pts runner-up";
    if (c.type === "exact") return `${c.points} pt${c.points === 1 ? "" : "s"} if right`;
    if (c.type === "ranking") return "5 / 3 / 1 for the closest rankings";
    return "5 / 3 / 1 for the closest";
  }

  function picksByPlayer() {
    const d = state.data;
    if (!state.player) state.player = d.players[0].id;
    const chips = `<div class="chips">${d.players.map((p) => `<button data-player="${esc(p.id)}" aria-pressed="${p.id === state.player}">${esc(p.name)}</button>`).join("")}</div>`;
    let total = 0;
    const rows = d.categories.map((c) => {
      const pts = c.points_awarded[state.player] || 0;
      total += pts;
      const res = resultText(c);
      return `<li class="${pts ? "scored" : ""}"><span class="who" style="font-weight:500">${esc(c.name)}</span><span class="pick">${pickText(c, c.picks[state.player])}${res ? `<span class="sub2">${c.status === "live" ? "now" : "result"}: ${res.replace(/<\/?b>/g, "")}</span>` : ""}</span>${ptsBadge(pts)}</li>`;
    }).join("");
    return chips + `<div class="card"><div class="cat-head"><h3>${esc(playerName(state.player))}'s picks</h3><span class="pts p5">${total} pts</span></div>
      <ul class="rows byplayer">${rows}</ul></div>`;
  }

  function picksGrid() {
    const d = state.data;
    const head = `<tr><th class="catcol">Category</th>${d.players.map((p) => `<th>${esc(p.name)}</th>`).join("")}<th>Result</th></tr>`;
    const totals = {};
    const body = d.categories.map((c) => {
      const cells = d.players.map((p) => {
        const pts = c.points_awarded[p.id] || 0;
        totals[p.id] = (totals[p.id] || 0) + pts;
        return `<td class="${pts ? "hit" : ""}">${pickText(c, c.picks[p.id])}${pts ? ptsBadge(pts) : ""}</td>`;
      }).join("");
      return `<tr><td class="catcol">${esc(c.name)}<div class="meta">${chip(c.status)}</div></td>${cells}<td>${resultText(c) || "—"}</td></tr>`;
    }).join("");
    const total = `<tr class="total"><td class="catcol">Total (incl. projected)</td>${d.players.map((p) => `<td>${totals[p.id]}</td>`).join("")}<td></td></tr>`;
    return `<div class="scroll" style="margin-top:12px"><table class="pickgrid"><thead>${head}</thead><tbody>${body}${total}</tbody></table></div>`;
  }

  // ---------------------------------------------------------------- schedule
  function schedItem(c) {
    const d = parseDate(c.date);
    const res = resultText(c);
    const sc = scorers(c);
    return `<li><div class="date"><span class="m">${d ? MONTHS[d.getMonth()] : ""}</span><span class="d">${d ? d.getDate() : ""}</span><span class="y">${d ? d.getFullYear() : ""}</span></div>
      <div><div class="cat-head"><h3>${esc(c.name)}</h3>${chip(c.status)}</div>
      ${res ? `<div>${c.status === "live" ? "Right now: " : ""}${res}</div>` : `<div class="meta">${pointsLabel(c)}</div>`}
      ${sc ? `<div class="scorers">${c.status === "live" ? "On pace: " : ""}${sc}</div>` : ""}</div></li>`;
  }

  function schedule() {
    const cats = [...state.data.categories];
    const done = cats.filter((c) => c.status === "final").sort((a, b) => (b.date || "").localeCompare(a.date || ""));
    const open = cats.filter((c) => c.status !== "final").sort((a, b) => (a.date || "").localeCompare(b.date || ""));
    let html = "";
    if (isPreview()) html += `<p class="note">Here's what's on the calendar for ${esc(state.data.season.year)}. Dates are approximate until each event is scheduled.</p>`;
    if (open.length) html += `<h2>${isPreview() ? "On the calendar" : "Still to be decided"}</h2><div class="card"><ul class="sched">${open.map(schedItem).join("")}</ul></div>`;
    if (done.length) html += `<h2>Decided</h2><div class="card"><ul class="sched">${done.map(schedItem).join("")}</ul></div>`;
    return html;
  }

  // ---------------------------------------------------------------- markets
  function markets() {
    const d = state.data;
    const cats = d.categories.filter((c) => c.group === "Markets" || c.type === "closest" || c.type === "ranking");
    const asOf = d.prices_as_of && isActive() ? `<p class="note">Prices update automatically each day after the market closes (last: ${esc(fmtStamp(d.prices_as_of))}). Final numbers are locked in on ${esc(fmtDate(d.season.settlement_date))}.</p>` : "";
    const startNote = d.prices_start_date ? ` "Start" is the price on ${esc(fmtDate(d.prices_start_date))}, when picks closed.` : "";
    return `<p class="note">How close everyone is right now.${startNote}</p>${asOf}<div class="grid two" style="margin-top:12px">${cats.map(marketCard).join("")}</div>`;
  }

  function marketCard(c) {
    if (c.type === "ranking") {
      const order = (c.result || {}).order;
      const rows = Object.keys(c.picks).sort((a, b) => ((c.detail[a] || {}).score ?? 99) - ((c.detail[b] || {}).score ?? 99)).map((p) => {
        const det = c.detail[p] || {};
        return `<li class="${c.points_awarded[p] ? "scored" : ""}"><span class="who">${esc(playerName(p))}</span><span class="pick">${pickText(c, c.picks[p])}<span class="sub2">${det.score !== undefined ? det.score + " spots off" : esc(det.error || "")}</span></span>${ptsBadge(c.points_awarded[p])}</li>`;
      }).join("");
      const caps = state.data.market_caps || {};
      const capText = (t) => (caps[t] ? ` <span class="cap">$${(caps[t] / 1e12).toFixed(2)}T</span>` : "");
      const capsNote = Object.keys(caps).length && state.data.prices_as_of
        ? `<div class="meta">Market caps as of ${esc(fmtStamp(state.data.prices_as_of))}</div>` : "";
      return `<div class="card"><div class="cat-head"><h3>${esc(c.name)}</h3>${chip(c.status)}</div>
        ${order ? `<div class="meta">${c.status === "final" ? "Final" : "Current"} order by market cap:</div><ol class="order">${order.map((t) => `<li>${esc(t)}${capText(t)}</li>`).join("")}</ol>${capsNote}` : ""}
        <ul class="rows">${rows}</ul></div>`;
    }
    if (c.type !== "closest") return catCard(c);
    const m = c.market || {};
    const now = (c.result || {}).value;
    let change = "";
    if (m.start && now) {
      const pct = ((now - m.start) / m.start) * 100;
      change = `<span class="${pct >= 0 ? "up" : "down"}">${pct >= 0 ? "▲" : "▼"} ${Math.abs(pct).toFixed(1)}%</span>`;
    }
    const rows = Object.keys(c.picks).sort((a, b) => ((c.detail[a] || {}).distance ?? 1e18) - ((c.detail[b] || {}).distance ?? 1e18)).map((p) => {
      const det = c.detail[p] || {};
      const pick = Number(c.picks[p]);
      const dir = now !== undefined && now !== null && !Number.isNaN(pick) ? (pick > now ? "high" : pick < now ? "low" : "exact") : "";
      return `<li class="${c.points_awarded[p] ? "scored" : ""}"><span class="who">${esc(playerName(p))}</span><span class="pick">${pickText(c, c.picks[p])}${det.distance !== undefined ? `<span class="sub2">off by ${fmtValue(det.distance, c.unit)}${dir && dir !== "exact" ? " (" + dir + ")" : ""}</span>` : ""}</span>${ptsBadge(c.points_awarded[p])}</li>`;
    }).join("");
    return `<div class="card"><div class="cat-head"><h3>${esc(c.name)}</h3>${chip(c.status)}</div>
      <div class="mk-top"><span class="mk-now">${fmtValue(now, c.unit)}</span>${change}${m.start ? `<span class="meta">start ${fmtValue(m.start, c.unit)}</span>` : ""}</div>
      <ul class="rows">${rows}</ul></div>`;
  }

  // ---------------------------------------------------------------- history
  function historyTab() {
    const hist = state.index.history || [];
    const hof = hist.length
      ? `<ul class="hof">${hist.map((h) => `<li><b>${esc(h.season)}</b> · ${esc(h.champions.map((c) => (state.index.players[c] || { name: c }).name).join(" & "))}${h.points ? ` · ${h.points} pts` : ""}</li>`).join("")}</ul>`
      : `<p>Coming soon. Robert is double-checking past results before the champions go up on the wall.</p>`;
    const seasons = state.index.seasons.map((s) => `<li><a href="#standings/${esc(s.id)}" data-season="${esc(s.id)}">${esc(s.title)}</a> <span class="meta">· ${s.status === "final" ? "settled" : "settles"} ${esc(fmtDate(s.settlement_date))}${s.status === "active" ? " (in progress)" : s.status === "planning" || s.status === "picks_open" ? " (picks coming soon)" : ""}</span></li>`).join("");
    return `<h2>Hall of Champions</h2><div class="card" style="display:flex;gap:14px;align-items:flex-start">${JACKET}<div style="flex:1">${hof}</div></div>
      <h2>Seasons</h2><div class="card"><ul class="hof">${seasons}</ul></div>`;
  }

  // ---------------------------------------------------------------- rules
  function rules() {
    return `<h2>How it works</h2><div class="card rules"><dl>
      <dt>The tradition</dt><dd>Everyone predicts the coming year in sports, markets and politics. At the next Gentlemen's Luncheon we crown the winner, who (in addition to collecting $20 from each player) receives the coveted burgundy jacket.</dd>
      <dt>When</dt><dd>Even years settle at Thanksgiving, odd years at Christmas. Market picks use the closing price on the last trading day before the holiday. Picks for next year's pool are due approx. one week after the lunch.</dd>
      <dt>Ties</dt><dd>If two or more players tie for first, they are Co-Champions.</dd></dl></div>
      <h2>Scoring</h2><div class="card rules"><table>
      <tr><th>Type</th><th>Points</th></tr>
      <tr><td>Pick the champion (Super Bowl, Masters, World Series…)</td><td><b>5</b> if your pick wins, <b>3</b> if your pick is the runner-up</td></tr>
      <tr><td>Closest number (S&amp;P 500, gold, oil, Bitcoin, stocks)</td><td>Closest gets <b>5</b>, next <b>3</b>, next <b>1</b>. Over or under both count. Ties share the points, and the next-closest still gets the next tier.</td></tr>
      <tr><td>Ranking (e.g., the Magnificent 7 by market cap)</td><td>Add up how many spots off you are for each company. Lowest total gets <b>5</b>, then <b>3</b>, then <b>1</b>.</td></tr>
      <tr><td>Right answer (elections, props)</td><td><b>3</b> for everyone who gets it right</td></tr>
      <tr><td>Super Bowl coin flip</td><td><b>1</b></td></tr></table></div>
      <h2>How the Mag 7 ranking is scored</h2><div class="card rules">
      <p>You rank the seven companies from largest market cap (1st) to smallest (7th). On settlement day we line up the real order.</p>
      <ol>
        <li><b>Count how far off each company is.</b> If you put Nvidia 2nd and it actually finishes 5th, that's 3 spots off. A company you placed exactly right is 0.</li>
        <li><b>Add up all seven.</b> That total is your score. Lower is better, and a perfect ranking scores 0.</li>
        <li><b>Lowest score gets 5 points</b>, second lowest gets 3, third lowest gets 1. If players tie, they get the same points, and the next score still gets the next tier.</li>
      </ol>
      <p class="note"><b>Example.</b> Actual order: AAPL, NVDA, MSFT, GOOG, AMZN, META, TSLA. You picked NVDA, AAPL, MSFT, GOOG, AMZN, TSLA, META.
      NVDA and AAPL are each 1 spot off, and TSLA and META are each 1 spot off. Everything else is exact, so your score is 1 + 1 + 1 + 1 = <b>4</b>.</p></div>`;
  }

  // ---------------------------------------------------------------- events
  document.addEventListener("click", async (e) => {
    const t = e.target.closest("[data-tab],[data-pv],[data-player],[data-season]");
    if (!t) return;
    if (t.dataset.tab) { state.tab = t.dataset.tab; render(); window.scrollTo(0, 0); }
    else if (t.dataset.pv) { state.picksView = t.dataset.pv; render(); }
    else if (t.dataset.player) { state.player = t.dataset.player; render(); }
    else if (t.dataset.season) { e.preventDefault(); state.season = t.dataset.season; state.tab = "standings"; await loadSeason(state.season); render(); }
  });
  $("#season").addEventListener("change", async (e) => { state.season = e.target.value; await loadSeason(state.season); render(); });
  window.addEventListener("hashchange", async () => {
    state.season = state.index.active;
    readHash();
    await loadSeason(state.season);
    render();
  });

  (async function init() {
    try {
      const res = await fetch("data/index.json", { cache: "no-cache" });
      state.index = await res.json();
      state.season = state.index.active;
      readHash();
      if (!state.index.seasons.some((s) => s.id === state.season)) state.season = state.index.active;
      await loadSeason(state.season);
      render();
    } catch (err) {
      $("#view").innerHTML = `<p class="loading">Couldn't load the standings. Try refreshing the page.</p>`;
      console.error(err);
    }
  })();
})();
